with recent_orders as (select * from orders where customer_id is not null and shipping_fee is not null), agg as (select date_trunc('MONTH', order_date) as order_month, channel, min(order_date) as min_order_date, round(stddev(shipping_fee), 2) as stddev_shipping_fee from recent_orders group by date_trunc('MONTH', order_date), channel) select order_month, channel, min_order_date, stddev_shipping_fee from agg;
